+    let event_names: Vec<&str> =
+        text.lines().filter_map(|line| line.strip_prefix("event: ")).collect();
+    assert_eq!(event_names.len(), payloads.len(), "{text}");
+    for (index, (event_name, payload)) in event_names.iter().zip(&payloads).enumerate() {
